1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"math/big"
9		"sort"
10	)
11	
12	// 离线流水对账：把外部支付渠道提供的有序流水与本地账本逐笔核对。
13	// 对账是只读操作，不改变余额、历史或账本文件。
14	//
15	// 逐条结果（保持输入顺序）有四种：
16	//   - matched：编号命中一条成功记录，且全部核对字段一致；
17	//   - field_mismatch：编号命中成功记录，但至少一个字段不同（逐个列出差异）；
18	//   - missing_in_ledger：账本中没有该编号的成功记录；
19	//   - duplicate：同一(kind,id)在输入中出现多次，整组全部标为重复并附全部
20	//     输入位置，不再判断字段差异，也不再把对应账本记录列为缺失。
21	//
22	// 付款编号与退款编号分别匹配，同名也不会混为一笔。只核对成功记录：
23	// 已退款的付款仍按原扣款核对，退款单独核对。账本中没有任何对应流水的成功
24	// 记录另列缺失（先按付款成功顺序，再按退款成功顺序）。
25	
26	const (
27		ReconMatched         = "matched"
28		ReconFieldMismatch   = "field_mismatch"
29		ReconMissingInLedger = "missing_in_ledger"
30		ReconDuplicate       = "duplicate"
31	)
32	
33	// amountJSON 是必须提供、且为 int64 整数的金额。
34	// 使用指针 + 自定义解码区分“缺省/null/非数字/越界”等情形。
35	type amountJSON struct {
36		v int64
37	}
38	
39	func (a *amountJSON) UnmarshalJSON(data []byte) error {
40		if string(data) == "null" {
41			return fmt.Errorf("amount must be an int64 integer, not null")
42		}
43		dec := json.NewDecoder(bytes.NewReader(data))
44		var v int64
45		if err := dec.Decode(&v); err != nil {
46			return err
47		}
48		// 单个数字字面量必须恰好结束。
49		if tok, err := dec.Token(); err != io.EOF {
50			if err == nil {
51				return fmt.Errorf("invalid integer amount (unexpected token %v)", tok)
52			}
53			return err
54		}
55		a.v = v
56		return nil
57	}
58	
59	// flowEntryJSON 是流水的严格解码形态。未知字段按标准库惯例忽略。
60	type flowEntryJSON struct {
61		Kind         string      `json:"kind"`
62		ID           string      `json:"id"`
63		Account      string      `json:"account"`
64		Asset        string      `json:"asset"`
65		Amount       *amountJSON `json:"amount"`
66		Fee          *amountJSON `json:"fee"`
67		Charged      *amountJSON `json:"charged"`
68		SettlementID string      `json:"settlement_id"`
69	}
70	
71	// flowRequestJSON 是对账输入：{"entries":[...]}。
72	type flowRequestJSON struct {
73		Entries []flowEntryJSON `json:"entries"`
74	}
75	
76	// FlowEntry 是校验通过后的一条流水。Index 是从 0 开始的输入位置。
77	type FlowEntry struct {
78		Index        int
79		Kind         string
80		ID           string
81		Account      string
82		Asset        string
83		Amount       int64
84		Fee          int64
85		Charged      int64
86		SettlementID string // 仅退款有意义
87	}
88	
89	// FieldDiff 是一个不同字段：账本值与流水值逐字并列。
90	type FieldDiff struct {
91		Field  string `json:"field"`
92		Ledger string `json:"ledger"`
93		Flow   string `json:"flow"`
94	}
95	
96	// ReconRecordRef 指向一条账本成功记录，并携带其关联记录（付款被退时的退款
97	// 编号、退款的原付款编号），使每个能定位到账本的结果都可追溯。
98	type ReconRecordRef struct {
99		Kind         string `json:"kind"`
100		ID           string `json:"id"`
101		Account      string `json:"account"`
102		Asset        string `json:"asset"`
103		Amount       int64  `json:"amount"`
104		Fee          int64  `json:"fee"`
105		Charged      int64  `json:"charged"`
106		Seq          int64  `json:"seq"`
107		SettlementID string `json:"settlement_id,omitempty"` // 退款记录：原付款编号
108		RefundID     string `json:"refund_id,omitempty"`     // 结算已被退款时：退款编号
109		RefundSeq    int64  `json:"refund_seq,omitempty"`
110	}
111	
112	// ReconResult 是一条输入流水的核对结果，顺序与输入一致。
113	type ReconResult struct {
114		Index     int             `json:"index"`
115		Kind      string          `json:"kind"`
116		ID        string          `json:"id"`
117		Status    string          `json:"status"`
118		Positions []int           `json:"positions,omitempty"` // duplicate：整组全部输入位置
119		Diffs     []FieldDiff     `json:"diffs,omitempty"`
120		Record    *ReconRecordRef `json:"record,omitempty"` // 命中账本记录时带上，可追溯关联结算/退款
121	}
122	
123	// ReconTotalRow 是一个 (账户, 资产) 组合单侧的金额汇总。金额使用十进制整数
124	// 字符串，累计可超过 int64 仍保持精确；不同资产各自一行，不相加、不抵消。
125	type ReconTotalRow struct {
126		Account       string `json:"account"`
127		Asset         string `json:"asset"`
128		ChargedTotal  string `json:"charged_total"`
129		RefundedTotal string `json:"refunded_total"`
130		NetCharged    string `json:"net_charged"`
131	}
132	
133	// ReconNetDiff 是一个组合的净扣款差额，方向为流水减账本。
134	type ReconNetDiff struct {
135		Account          string `json:"account"`
136		Asset            string `json:"asset"`
137		LedgerNetCharged string `json:"ledger_net_charged"`
138		FlowNetCharged   string `json:"flow_net_charged"`
139		NetChargedDiff   string `json:"net_charged_diff"`
140	}
141	
142	// ReconTotals 是账本侧与流水侧各自的汇总。
143	type ReconTotals struct {
144		Ledger []ReconTotalRow `json:"ledger"`
145		Flow   []ReconTotalRow `json:"flow"`
146	}
147	
148	// ReconReport 是一次对账的完整报告。
149	type ReconReport struct {
150		Results         []ReconResult    `json:"results"`
151		MissingPayments []ReconRecordRef `json:"missing_payments"`
152		MissingRefunds  []ReconRecordRef `json:"missing_refunds"`
153		Totals          ReconTotals      `json:"totals"`
154		NetDiff         []ReconNetDiff   `json:"net_diff"`
155		MaxPaymentSeq   int64            `json:"max_payment_seq"`
156		MaxRefundSeq    int64            `json:"max_refund_seq"`
157	}
158	
159	// ParseReconcileRequest 严格解析对账输入。
160	// 字段缺失、类型不符、未知 kind、数值越界或非法 JSON 均返回 invalid_parameter；
161	// 任一条目不合法则整次拒绝，不产生部分结果。
162	func ParseReconcileRequest(raw []byte) ([]FlowEntry, error) {
163		dec := json.NewDecoder(bytes.NewReader(raw))
164		var req flowRequestJSON
165		if err := dec.Decode(&req); err != nil {
166			return nil, ledgerError(ErrInvalid, "parse reconcile JSON: %v", err)
167		}
168		if tok, err := dec.Token(); err != io.EOF {
169			if err == nil {
170				return nil, ledgerError(ErrInvalid, "reconcile: unexpected trailing content after JSON document (token %v)", tok)
171			}
172			return nil, ledgerError(ErrInvalid, "reconcile: %v", err)
173		}
174		// entries 必须显式提供；{} 等缺省列表的文档视为非法输入，
175		// 只有 {"entries":[]} 才表示“空列表：全部账本记录缺失”。
176		if req.Entries == nil {
177			return nil, ledgerError(ErrInvalid, "reconcile: entries is required")
178		}
179	
180		entries := make([]FlowEntry, 0, len(req.Entries))
181		for i, e := range req.Entries {
182			at := func(msg string) error {
183				return ledgerError(ErrInvalid, "reconcile entry %d: %s", i, msg)
184			}
185			if e.Kind != "payment" && e.Kind != "refund" {
186				return nil, at(fmt.Sprintf("unknown kind %q (want payment or refund)", e.Kind))
187			}
188			if e.ID == "" {
189				return nil, at("id must not be empty")
190			}
191			if e.Account == "" {
192				return nil, at("account must not be empty")
193			}
194			if e.Asset == "" {
195				return nil, at("asset must not be empty")
196			}
197			if e.Amount == nil {
198				return nil, at("amount is required and must be an int64 integer")
199			}
200			if e.Fee == nil {
201				return nil, at("fee is required and must be an int64 integer")
202			}
203			if e.Charged == nil {
204				return nil, at("charged is required and must be an int64 integer")
205			}
206			if e.Amount.v <= 0 {
207				return nil, at("amount must be a positive int64")
208			}
209			if e.Fee.v < 0 {
210				return nil, at("fee must be a non-negative int64")
211			}
212			if e.Charged.v <= 0 {
213				return nil, at("charged must be a positive int64")
214			}
215			if e.Kind == "refund" && e.SettlementID == "" {
216				return nil, at("settlement_id must not be empty for a refund")
217			}
218			entries = append(entries, FlowEntry{
219				Index:        i,
220				Kind:         e.Kind,
221				ID:           e.ID,
222				Account:      e.Account,
223				Asset:        e.Asset,
224				Amount:       e.Amount.v,
225				Fee:          e.Fee.v,
226				Charged:      e.Charged.v,
227				SettlementID: e.SettlementID,
228			})
229		}
230		return entries, nil
231	}
232	
233	// reconSide 累计单侧（账本或流水）的金额。流水侧可能包含账本外的组合，
234	// 且累计允许超过 int64，因此一律用大整数。
235	type reconSide struct {
236		charged  map[balanceKey]*big.Int
237		refunded map[balanceKey]*big.Int
238	}
239	
240	func newReconSide() reconSide {
241		return reconSide{charged: map[balanceKey]*big.Int{}, refunded: map[balanceKey]*big.Int{}}
242	}
243	
244	func (s *reconSide) addCharged(k balanceKey, v int64) {
245		x := s.charged[k]
246		if x == nil {
247			x = new(big.Int)
248			s.charged[k] = x
249		}
250		x.Add(x, big.NewInt(v))
251	}
252	
253	func (s *reconSide) addRefund(k balanceKey, v int64) {
254		x := s.refunded[k]
255		if x == nil {
256			x = new(big.Int)
257			s.refunded[k] = x
258		}
259		x.Add(x, big.NewInt(v))
260	}
261	
262	// ReconcileFlow 对一批外部流水与当前账本状态做只读对账。
263	// 整份报告在同一把账本互斥锁内生成，因而对应同一个完整账本状态，
264	// 与并发的 Submit/Refund 串行，不会读到半截历史。
265	func (l *Ledger) ReconcileFlow(entries []FlowEntry) (*ReconReport, error) {
266		if err := l.beginOp(); err != nil {
267			return nil, err
268		}
269		defer l.endOp()
270		l.reg.mu.Lock()
271		defer l.reg.mu.Unlock()
272	
273		st := l.stateView()
274	
275		// 结算编号 / 退款编号各自索引：同名编号也不会混为一笔。
276		payByID := make(map[string]*Record, len(st.Settlements))
277		for i := range st.Settlements {
278			payByID[st.Settlements[i].ID] = &st.Settlements[i]
279		}
280		refundByID := make(map[string]*RefundRecord, len(st.Refunds))
281		refundOfPay := make(map[string]*RefundRecord, len(st.Refunds))
282		for i := range st.Refunds {
283			r := &st.Refunds[i]
284			refundByID[r.ID] = r
285			refundOfPay[r.SettlementID] = r
286		}
287	
288		// 统计每个 (kind,id) 在输入中出现的全部位置：出现多次则整组重复，
289		// 无论内容是否相同。
290		type idUse struct{ positions []int }
291		paySeen := map[string]*idUse{}
292		refundSeen := map[string]*idUse{}
293		for i := range entries {
294			e := &entries[i]
295			m := paySeen
296			if e.Kind == "refund" {
297				m = refundSeen
298			}
299			u := m[e.ID]
300			if u == nil {
301				u = &idUse{}
302				m[e.ID] = u
303			}
304			u.positions = append(u.positions, e.Index)
305		}
306	
307		report := &ReconReport{
308			Results:         make([]ReconResult, 0, len(entries)),
309			MissingPayments: []ReconRecordRef{},
310			MissingRefunds:  []ReconRecordRef{},
311			NetDiff:         []ReconNetDiff{},
312			MaxPaymentSeq:   int64(len(st.Settlements)),
313			MaxRefundSeq:    int64(len(st.Refunds)),
314		}
315	
316		ledgerSide := newReconSide()
317		flowSide := newReconSide()
318		coveredPay := map[string]bool{} // 唯一且命中账本的付款编号（含字段不符）
319		coveredRefund := map[string]bool{}
320	
321		// 逐条结果（保持输入顺序）。
322		for i := range entries {
323			e := &entries[i]
324			res := ReconResult{Index: e.Index, Kind: e.Kind, ID: e.ID}
325			k := balanceKey{e.Account, e.Asset}
326	
327			uses := paySeen[e.ID]
328			if e.Kind == "refund" {
329				uses = refundSeen[e.ID]
330			}
331	
332			// 1. 重复组：不判字段、不占缺失；流水侧合计仍包含每一条。
333			if len(uses.positions) > 1 {
334				res.Status = ReconDuplicate
335				res.Positions = append([]int(nil), uses.positions...)
336				if e.Kind == "payment" {
337					flowSide.addCharged(k, e.Charged)
338					if rec := payByID[e.ID]; rec != nil {
339						ref := paymentRef(rec, refundOfPay[e.ID])
340						res.Record = &ref
341					}
342				} else {
343					flowSide.addRefund(k, e.Charged)
344					if rec := refundByID[e.ID]; rec != nil {
345						ref := refundRef(rec)
346						res.Record = &ref
347					}
348				}
349				report.Results = append(report.Results, res)
350				continue
351			}
352	
353			// 2. 唯一条目：命中则逐字段核对，否则账本缺这笔。
354			if e.Kind == "payment" {
355				flowSide.addCharged(k, e.Charged)
356				if rec := payByID[e.ID]; rec != nil {
357					coveredPay[e.ID] = true
358					ref := paymentRef(rec, refundOfPay[e.ID])
359					res.Record = &ref
360					if diffs := comparePayment(rec, e); len(diffs) > 0 {
361						res.Status = ReconFieldMismatch
362						res.Diffs = diffs
363					} else {
364						res.Status = ReconMatched
365					}
366				} else {
367					res.Status = ReconMissingInLedger
368				}
369			} else {
370				flowSide.addRefund(k, e.Charged)
371				if rec := refundByID[e.ID]; rec != nil {
372					coveredRefund[e.ID] = true
373					ref := refundRef(rec)
374					res.Record = &ref
375					if diffs := compareRefund(rec, e); len(diffs) > 0 {
376						res.Status = ReconFieldMismatch
377						res.Diffs = diffs
378					} else {
379						res.Status = ReconMatched
380					}
381				} else {
382					res.Status = ReconMissingInLedger
383				}
384			}
385			report.Results = append(report.Results, res)
386		}
387	
388		// 账本侧合计恒为完整账本：所有成功结算与成功退款。
389		// 已退款的付款仍计入原扣款，退款单独计入退款侧。
390		for i := range st.Settlements {
391			r := &st.Settlements[i]
392			ledgerSide.addCharged(balanceKey{r.Account, r.Asset}, r.Charged)
393		}
394		for i := range st.Refunds {
395			r := &st.Refunds[i]
396			ledgerSide.addRefund(balanceKey{r.Account, r.Asset}, r.Charged)
397		}
398	
399		// 账本有、但流水未覆盖的成功记录另列缺失（先付款后退款，各按成功顺序）。
400		// 唯一出现即算覆盖（含字段不符）；重复组对应记录按规则不列为缺失。
401		for i := range st.Settlements {
402			r := &st.Settlements[i]
403			if coveredPay[r.ID] {
404				continue
405			}
406			if u := paySeen[r.ID]; u != nil && len(u.positions) > 1 {
407				continue
408			}
409			report.MissingPayments = append(report.MissingPayments, paymentRef(r, refundOfPay[r.ID]))
410		}
411		for i := range st.Refunds {
412			r := &st.Refunds[i]
413			if coveredRefund[r.ID] {
414				continue
415			}
416			if u := refundSeen[r.ID]; u != nil && len(u.positions) > 1 {
417				continue
418			}
419			report.MissingRefunds = append(report.MissingRefunds, refundRef(r))
420		}
421	
422		report.Totals = ReconTotals{
423			Ledger: buildTotalRows(ledgerSide),
424			Flow:   buildTotalRows(flowSide),
425		}
426		report.NetDiff = buildNetDiff(ledgerSide, flowSide)
427		return report, nil
428	}
429	
430	// comparePayment 比较付款的账户、资产、amount、fee、charged 五个字段。
431	func comparePayment(r *Record, e *FlowEntry) []FieldDiff {
432		var diffs []FieldDiff
433		addStr := func(field, ledger, flow string) {
434			if ledger != flow {
435				diffs = append(diffs, FieldDiff{Field: field, Ledger: ledger, Flow: flow})
436			}
437		}
438		addInt := func(field string, ledger, flow int64) {
439			if ledger != flow {
440				diffs = append(diffs, FieldDiff{Field: field, Ledger: fmt.Sprintf("%d", ledger), Flow: fmt.Sprintf("%d", flow)})
441			}
442		}
443		addStr("account", r.Account, e.Account)
444		addStr("asset", r.Asset, e.Asset)
445		addInt("amount", r.Amount, e.Amount)
446		addInt("fee", r.Fee, e.Fee)
447		addInt("charged", r.Charged, e.Charged)
448		return diffs
449	}
450	
451	// compareRefund 比较退款的账户、资产、三个金额及原付款编号。
452	func compareRefund(r *RefundRecord, e *FlowEntry) []FieldDiff {
453		var diffs []FieldDiff
454		addStr := func(field, ledger, flow string) {
455			if ledger != flow {
456				diffs = append(diffs, FieldDiff{Field: field, Ledger: ledger, Flow: flow})
457			}
458		}
459		addInt := func(field string, ledger, flow int64) {
460			if ledger != flow {
461				diffs = append(diffs, FieldDiff{Field: field, Ledger: fmt.Sprintf("%d", ledger), Flow: fmt.Sprintf("%d", flow)})
462			}
463		}
464		addStr("account", r.Account, e.Account)
465		addStr("asset", r.Asset, e.Asset)
466		addInt("amount", r.Amount, e.Amount)
467		addInt("fee", r.Fee, e.Fee)
468		addInt("charged", r.Charged, e.Charged)
469		addStr("settlement_id", r.SettlementID, e.SettlementID)
470		return diffs
471	}
472	
473	func paymentRef(r *Record, rf *RefundRecord) ReconRecordRef {
474		ref := ReconRecordRef{
475			Kind:    "payment",
476			ID:      r.ID,
477			Account: r.Account,
478			Asset:   r.Asset,
479			Amount:  r.Amount,
480			Fee:     r.Fee,
481			Charged: r.Charged,
482			Seq:     r.Seq,
483		}
484		if rf != nil {
485			ref.RefundID = rf.ID
486			ref.RefundSeq = rf.Seq
487		}
488		return ref
489	}
490	
491	func refundRef(r *RefundRecord) ReconRecordRef {
492		return ReconRecordRef{
493			Kind:         "refund",
494			ID:           r.ID,
495			Account:      r.Account,
496			Asset:        r.Asset,
497			Amount:       r.Amount,
498			Fee:          r.Fee,
499			Charged:      r.Charged,
500			Seq:          r.Seq,
501			SettlementID: r.SettlementID,
502		}
503	}
504	
505	// sideNet 返回某组合的净扣款（扣款 - 退款）。
506	func sideNet(side reconSide, k balanceKey) *big.Int {
507		charged := new(big.Int)
508		if x := side.charged[k]; x != nil {
509			charged.Set(x)
510		}
511		refunded := new(big.Int)
512		if x := side.refunded[k]; x != nil {
513			refunded.Set(x)
514		}
515		return charged.Sub(charged, refunded)
516	}
517	
518	func allKeys(a, b reconSide) []balanceKey {
519		seen := map[balanceKey]bool{}
520		var keys []balanceKey
521		add := func(m map[balanceKey]*big.Int) {
522			for k := range m {
523				if !seen[k] {
524					seen[k] = true
525					keys = append(keys, k)
526				}
527			}
528		}
529		add(a.charged)
530		add(a.refunded)
531		add(b.charged)
532		add(b.refunded)
533		sort.Slice(keys, func(i, j int) bool {
534			if keys[i].account != keys[j].account {
535				return keys[i].account < keys[j].account
536			}
537			return keys[i].asset < keys[j].asset
538		})
539		return keys
540	}
541	
542	// buildTotalRows 按账户、资产排序输出单侧汇总；净扣款 = 扣款 - 退款。
543	func buildTotalRows(side reconSide) []ReconTotalRow {
544		keys := allKeys(side, reconSide{})
545		out := make([]ReconTotalRow, 0, len(keys))
546		for _, k := range keys {
547			charged := new(big.Int)
548			if x := side.charged[k]; x != nil {
549				charged.Set(x)
550			}
551			refunded := new(big.Int)
552			if x := side.refunded[k]; x != nil {
553				refunded.Set(x)
554			}
555			net := new(big.Int).Sub(new(big.Int).Set(charged), refunded)
556			out = append(out, ReconTotalRow{
557				Account:       k.account,
558				Asset:         k.asset,
559				ChargedTotal:  charged.String(),
560				RefundedTotal: refunded.String(),
561				NetCharged:    net.String(),
562			})
563		}
564		return out
565	}
566	
567	// buildNetDiff 输出每个（任一侧出现过的）组合的净扣款差额，方向为流水减账本。
568	func buildNetDiff(ledger, flow reconSide) []ReconNetDiff {
569		out := make([]ReconNetDiff, 0)
570		for _, k := range allKeys(ledger, flow) {
571			lNet := sideNet(ledger, k)
572			fNet := sideNet(flow, k)
573			diff := new(big.Int).Sub(new(big.Int).Set(fNet), lNet)
574			out = append(out, ReconNetDiff{
575				Account:          k.account,
576				Asset:            k.asset,
577				LedgerNetCharged: lNet.String(),
578				FlowNetCharged:   fNet.String(),
579				NetChargedDiff:   diff.String(),
580			})
581		}
582		return out
583	}
584

