499		entries, _ := ParseReconcileRequest([]byte(`{"entries":[
500		  {"kind":"payment","id":"p2","account":"aa-2","asset":"eth","amount":10,"fee":0,"charged":10},
501		  {"kind":"payment","id":"p2","account":"aa-2","asset":"eth","amount":10,"fee":0,"charged":10}
502		]}`))
