511		for _, r := range rep.Totals.Flow {
512			if r.Account == "aa-2" && r.Asset == "eth" {
513				ethFlow = r
514			}
515		}
516		for _, r := range rep.Totals.Ledger {
517			if r.Account == "aa-2" && r.Asset == "eth" {
518				ethLedger = r
519			}
520		}
521		if ethFlow.ChargedTotal != "20" || ethFlow.NetCharged != "20" {
