442		  {"kind":"payment","id":"p1","account":"aa-1","asset":"usdc","amount":1000,"fee":9,"charged":1003},
443		  {"kind":"payment","id":"p2","account":"aa-2","asset":"eth","amount":10,"fee":5,"charged":99},
444		  {"kind":"payment","id":"p2","account":"aa-2","asset":"eth","amount":10,"fee":5,"charged":99},
445		  {"kind":"refund","id":"rX","account":"aa-1","asset":"usdc","amount":1,"fee":0,"charged":1,"settlement_id":"p1"}
446		]}`
447		r := runCLIWith(t, []string{"reconcile", "-l", ledgerPath}, body)
448		if r.code != 0 {
449			t.Fatalf("reconcile: %s", r.err)
450		}
451		var rep struct {
452			Results []struct {
453				Status    string `json:"status"`
454				Positions []int  `json:"positions"`
455				Diffs     []struct {
456					Field string `json:"field"`
457				} `json:"diffs"`
458			} `json:"results"`
459			MissingPayments []struct {
460				ID string `json:"id"`
461			} `json:"missing_payments"`
462			MissingRefunds []struct {
